// Read whatever shape the Error Trigger handed us, then decide if this is a repeat.
const cfg = $('Set config: who to alert and how often').first().json;
const j = $json || {};
const wf = j.workflow || {};
const ex = j.execution || {};
const err = ex.error || (j.trigger && j.trigger.error) || {};

const nodeName = (err.node && (err.node.name || err.node.type)) || ex.lastNodeExecuted || 'unknown node';
const message = String(err.message || err.description || 'No error message was reported.');
const stackLines = String(err.stack || '').split('\n')
  .map((l) => l.trim()).filter(Boolean).slice(0, Number(cfg.maxStackLines) || 20);

// Alert storms are the reason people turn error alerts off. One alert per unique
// failure per cooldown window, counting how many were swallowed.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const key = [wf.id || wf.name || 'wf', nodeName, message.slice(0, 120)].join('::');
const now = Date.now();
const cooldownMs = (Number(cfg.cooldownMinutes) || 30) * 60000;
const prev = store.seen[key];

let shouldAlert = true;
let suppressedSince = 0;
if (prev && now - prev.first < cooldownMs) {
  prev.count = (prev.count || 1) + 1;
  shouldAlert = false;
  suppressedSince = prev.count;
} else {
  store.seen[key] = { first: now, count: 1 };
}

// Keep the store from growing without bound.
for (const k of Object.keys(store.seen)) {
  if (now - store.seen[k].first > cooldownMs * 20) delete store.seen[k];
}

const repeatCount = (store.seen[key] && store.seen[key].count) || 1;

return [{ json: {
  shouldAlert,
  suppressedSince,
  repeatCount,
  workflowName: wf.name || 'Unnamed workflow',
  workflowId: wf.id || '',
  executionId: ex.id || '',
  executionUrl: ex.url || '',
  mode: ex.mode || '',
  retryOf: ex.retryOf || '',
  nodeName,
  errorName: err.name || 'Error',
  message,
  description: String(err.description || ''),
  stack: stackLines.join('\n'),
  failedAt: new Date(now).toISOString(),
} }];

const cfg = $('Set config: who to alert and how often').first().json;
const e = $json;
const schema = { type: 'object', additionalProperties: false,
  required: ['severity', 'is_transient', 'summary', 'likely_cause', 'fix_steps'], properties: {
    severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
    is_transient: { type: 'boolean' },
    summary: { type: 'string' },
    likely_cause: { type: 'string' },
    fix_steps: { type: 'array', items: { type: 'string' } } } };

const system = 'You diagnose failed n8n workflow executions for the person who owns the workflow. ' +
  'Explain in plain English what went wrong, in terms of the automation, not of JavaScript internals. ' +
  'Set is_transient true only for things that fix themselves on a retry, such as a timeout, a 429 rate ' +
  'limit or a 5xx from an upstream API. Set it false for credential, permission, schema, expression and ' +
  'logic errors. fix_steps must be concrete actions taken inside n8n, naming the node where possible, ' +
  'at most four steps. Never invent node names, field names or credentials that do not appear in the ' +
  'input. If the cause is genuinely unclear, say so and give the next diagnostic step instead of a guess. ' +
  'Do not use em dashes.';

const user = [
  'WORKFLOW: ' + e.workflowName,
  'FAILING NODE: ' + e.nodeName,
  'ERROR TYPE: ' + e.errorName,
  'MESSAGE: ' + e.message,
  e.description ? 'DESCRIPTION: ' + e.description : '',
  'EXECUTION MODE: ' + (e.mode || 'unknown'),
  e.retryOf ? 'THIS WAS A RETRY OF: ' + e.retryOf : '',
  e.repeatCount > 1 ? 'THIS EXACT FAILURE HAS HAPPENED ' + e.repeatCount + ' TIMES IN THIS WINDOW' : '',
  e.stack ? '\nSTACK:\n' + e.stack : '',
].filter(Boolean).join('\n');

return [{ json: { body: {
  model: cfg.model, max_tokens: 1200, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

const cfg = $('Set config: who to alert and how often').first().json;
const e = $('Read the failure and check for repeats').first().json;
const blocks = ($json.content || []);
const text = (blocks.find((b) => b.type === 'text') || {}).text || '{}';

let d = {};
try { d = JSON.parse(text) || {}; } catch (err) {}

const severity = d.severity || 'medium';
const steps = Array.isArray(d.fix_steps) ? d.fix_steps : [];

// If the model gave us nothing usable, still send the raw failure. Never swallow an alert.
const summary = d.summary || 'The diagnosis could not be generated. The raw error is below.';

const subject = '[' + severity.toUpperCase() + '] ' + e.workflowName + ' failed at ' + e.nodeName;

const body = [
  summary,
  '',
  'WHAT FAILED',
  '  Workflow: ' + e.workflowName,
  '  Node:     ' + e.nodeName,
  '  Error:    ' + e.errorName + ': ' + e.message,
  '  When:     ' + e.failedAt,
  e.repeatCount > 1 ? '  Repeats:  ' + e.repeatCount + ' times in the last ' + cfg.cooldownMinutes + ' minutes' : '',
  d.is_transient ? '  Note:     this looks transient and may clear on a retry' : '',
  '',
  d.likely_cause ? 'LIKELY CAUSE\n  ' + d.likely_cause + '\n' : '',
  steps.length ? 'WHAT TO DO\n' + steps.map((s, i) => '  ' + (i + 1) + '. ' + s).join('\n') + '\n' : '',
  e.executionUrl ? 'OPEN THE FAILED RUN\n  ' + e.executionUrl + '\n' : '',
  e.stack ? 'STACK\n' + e.stack.split('\n').map((l) => '  ' + l).join('\n') : '',
].filter((l) => l !== '').join('\n');

return [{ json: {
  subject, body, severity,
  isTransient: !!d.is_transient,
  notifyTo: cfg.notifyTo,
  workflowName: e.workflowName,
  nodeName: e.nodeName,
} }];
